Ts = 1.0
w = np.array([0.5, 1.0, 1.5, 2.0, 3.0])

def cont(w):
    s = 1j*w
    return 1/(s+1)

def euler(w):  # forward Euler: s = (z-1)/Ts, z=e^{jwTs}
    z = np.exp(1j*w*Ts)
    s = (z-1)/Ts
    return 1/(s+1)

def bilinear(w):
    z = np.exp(1j*w*Ts)
    s = (2/Ts)*(z-1)/(z+1)
    return 1/(s+1)

def exact(w):
    z = np.exp(1j*w*Ts)
    # exact: H(z) = (1-e^{-Ts})/(z - e^{-Ts}) for 1/(s+1)
    return (1-np.exp(-Ts))/(z-np.exp(-Ts))

for name,f in [("cont",cont),("euler",euler),("bilinear",bilinear),("exact",exact)]:
